import{_ as r,o as l,c as e,a5 as g}from"./chunks/framework.DJo0M80U.js";const s=JSON.parse('{"title":"获取Get请求参数详解（附样例：非空、默认值、数组、对象）","description":"","frontmatter":{"title":"获取Get请求参数详解（附样例：非空、默认值、数组、对象）","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/获取Get请求参数详解（附样例：非空、默认值、数组、对象）.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/获取Get请求参数详解（附样例：非空、默认值、数组、对象）.md"}'),b={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/获取Get请求参数详解（附样例：非空、默认值、数组、对象）.md"};function o(a,t,n,i,d,h){return l(),e("div",null,[...t[0]||(t[0]=[g('<div><p>利用 <strong>Spring Boot</strong> 来制作 <strong>Web</strong> 应用，就必定会涉及到前端与后台之间互相传递参数。下面演示 <strong>Controller</strong> 如何接收以 <strong>GET</strong> 方式传递过来的参数。 <strong>一、参数直接在路径中</strong> （1）假设请求地址是如下这种 <strong>RESTful</strong> 风格，<strong>hangge</strong> 这个参数值直接放在路径里面：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>1</code></td><td>- （2）<strong>Controller</strong> 可以这么获取该参数：</td></tr></tbody></table><ul><li>| | |</li><li>|---|---|</li><li>| &lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;<code>|</code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;import org.springframework.web.bind.annotation.PathVariable;&lt;br&gt;import org.springframework.web.bind.annotation.RestController;&lt;br&gt;import org.springframework.web.bind.annotation.GetMapping;&lt;br&gt; &lt;br&gt;@RestController&lt;br&gt;public class HelloController {&lt;br&gt;    @GetMapping(&quot;/hello/{name}&quot;)&lt;br&gt;    public String hello(@PathVariable(&quot;name&quot;) String name) {&lt;br&gt;        return &quot;&lt;br&gt;<code>&lt;br&gt;&lt;br&gt;获取到的`name`是：&lt;br&gt;&lt;br&gt;</code>&lt;br&gt;&quot; + name;&lt;br&gt;    }&lt;br&gt;}&lt;br&gt;```| <a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></li></ul><p><strong>二、参数跟在</strong> <strong>?</strong> <strong>号后面</strong><strong>1</strong>**，获取参数的基本方法** （1）假设请求地址是如下这种传统方式，参数跟在问号后面：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>1</code></td><td>```&lt;br&gt;<a href="http://localhost:8080/hello?name=hangge" target="_blank" rel="noreferrer">http://localhost:8080/hello?name=hangge</a>&lt;br&gt;- （2）<strong>Controller</strong> 可以这么获取该参数：</td></tr></tbody></table><ul><li>| | |</li><li>|---|---|</li><li>| &lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;<code>|</code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;import org.springframework.web.bind.annotation.RequestParam;&lt;br&gt;import org.springframework.web.bind.annotation.RestController;&lt;br&gt;import org.springframework.web.bind.annotation.GetMapping;&lt;br&gt; &lt;br&gt;@RestController&lt;br&gt;public class HelloController {&lt;br&gt;    @GetMapping(&quot;/hello&quot;)&lt;br&gt;    public String hello(@RequestParam(&quot;name&quot;) String name) {&lt;br&gt;        return &quot;&lt;br&gt;<code>&lt;br&gt;&lt;br&gt;获取到的`name`是：&lt;br&gt;&lt;br&gt;</code>&lt;br&gt;&quot; + name;&lt;br&gt;    }&lt;br&gt;}&lt;br&gt;```| <a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></li></ul><p><strong>2</strong>**，参数没有传递的情况** （1）如果没有传递参数 <strong>Controller</strong> 将会报错，我们可以使用 <strong>required = false</strong> 标注参数是非必须的。</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;</code></td><td><code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;import org.springframework.web.bind.annotation.RequestParam;&lt;br&gt;import org.springframework.web.bind.annotation.RestController;&lt;br&gt;import org.springframework.web.bind.annotation.GetMapping;&lt;br&gt; &lt;br&gt;@RestController&lt;br&gt;public class HelloController \\{&lt;br&gt;    @GetMapping(&quot;/hello&quot;)&lt;br&gt;    public String hello(@RequestParam(name = &quot;name&quot;, required = false) String name) \\{&lt;br&gt;        return &quot;&lt;br&gt;</code>&lt;br&gt;&lt;br&gt;获取到的<code>name</code>是：&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;&quot; + name;&lt;br&gt;    \\}&lt;br&gt;\\}&lt;br&gt;</code></td></tr><tr><td><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></td><td></td></tr></tbody></table><p>（2）或者可以指定个默认值，当没有传递参数时自动使用默认值：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;</code></td><td><code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;import org.springframework.web.bind.annotation.RequestParam;&lt;br&gt;import org.springframework.web.bind.annotation.RestController;&lt;br&gt;import org.springframework.web.bind.annotation.GetMapping;&lt;br&gt; &lt;br&gt;@RestController&lt;br&gt;public class HelloController \\{&lt;br&gt;    @GetMapping(&quot;/hello&quot;)&lt;br&gt;    public String hello(@RequestParam(name = &quot;name&quot;, defaultValue = &quot;xxx&quot;) String name) \\{&lt;br&gt;        return &quot;&lt;br&gt;</code>&lt;br&gt;&lt;br&gt;获取到的<code>name</code>是：&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;&quot; + name;&lt;br&gt;    \\}&lt;br&gt;\\}&lt;br&gt;</code></td></tr><tr><td><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></td><td></td></tr></tbody></table><p><strong>3</strong>**，使用** <strong>map</strong> <strong>来接收参数</strong> （1）<strong>Controller</strong> 还可以直接使用 <strong>map</strong> 来接收所有的请求参数：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;14&lt;br&gt;15&lt;br&gt;</code></td><td><code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;import org.springframework.web.bind.annotation.RequestParam;&lt;br&gt;import org.springframework.web.bind.annotation.RestController;&lt;br&gt;import org.springframework.web.bind.annotation.GetMapping;&lt;br&gt; &lt;br&gt;import java.util.Map;&lt;br&gt; &lt;br&gt;@RestController&lt;br&gt;public class HelloController \\{&lt;br&gt;    @GetMapping(&quot;/hello&quot;)&lt;br&gt;    public String hello(@RequestParam Map\\&lt;String, Object\\&gt; params) \\{&lt;br&gt;        return &quot;name&lt;br&gt;</code>&lt;br&gt;&lt;br&gt;：&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;&quot; + params.get(&quot;name&quot;) + &quot;\\&lt;br\\&gt;age&lt;br&gt;</code>&lt;br&gt;&lt;br&gt;：&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;&quot; + params.get(&quot;age&quot;);&lt;br&gt;    \\}&lt;br&gt;\\}&lt;br&gt;</code></td></tr></tbody></table><p>（2）下面是一个简单的测试样例：</p><p><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></p><p><strong>4</strong>**，接收一个数组** （1）假设请求地址是如下这种，有多个同名参数：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>1</code></td><td>```&lt;br&gt;<a href="http://localhost:8080/hello?name=hangge&amp;name=google" target="_blank" rel="noreferrer">http://localhost:8080/hello?name=hangge&amp;name=google</a>&lt;br&gt;- （2）我们可以定义一个数组类型的参数来接收：</td></tr></tbody></table><ul><li>| | |</li><li>|---|---|</li><li>| &lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;14&lt;br&gt;15&lt;br&gt;16&lt;br&gt;17&lt;br&gt;<code>|</code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;import org.springframework.web.bind.annotation.RequestParam;&lt;br&gt;import org.springframework.web.bind.annotation.RestController;&lt;br&gt;import org.springframework.web.bind.annotation.GetMapping;&lt;br&gt; &lt;br&gt;@RestController&lt;br&gt;public class HelloController {&lt;br&gt;    @GetMapping(&quot;/hello&quot;)&lt;br&gt;    public String hello(@RequestParam(&quot;name&quot;) String[] names) {&lt;br&gt;        String result = &quot;&quot;;&lt;br&gt;        for(String name:names){&lt;br&gt;            result += name + &quot;&lt;br&gt;&quot;;&lt;br&gt;        }&lt;br&gt;        return result;&lt;br&gt;    }&lt;br&gt;}&lt;br&gt;```| <a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></li></ul><p><strong>附：使用对象来接收参数</strong><strong>1</strong>**，基本用法** （1）如果一个 <strong>get</strong> 请求的参数太多，我们构造一个对象来简化参数的接收方式：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;</code></td><td><code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;import org.springframework.web.bind.annotation.RestController;&lt;br&gt;import org.springframework.web.bind.annotation.GetMapping;&lt;br&gt; &lt;br&gt;@RestController&lt;br&gt;public class HelloController \\{&lt;br&gt;    @GetMapping(&quot;/hello&quot;)&lt;br&gt;    public String hello(User user) \\{&lt;br&gt;        return &quot;name&lt;br&gt;</code>&lt;br&gt;&lt;br&gt;：&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;&quot; + user.getName() + &quot;\\&lt;br\\&gt; age&lt;br&gt;</code>&lt;br&gt;&lt;br&gt;：&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;&quot; + user.getAge();&lt;br&gt;    \\}&lt;br&gt;\\}&lt;br&gt;</code></td></tr></tbody></table><p>（2）<strong>User</strong> 类的定义如下，到时可以直接将多个参数通过 <strong>getter</strong>、<strong>setter</strong> 方法注入到对象中去：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;14&lt;br&gt;15&lt;br&gt;16&lt;br&gt;17&lt;br&gt;18&lt;br&gt;19&lt;br&gt;20&lt;br&gt;21&lt;br&gt;22&lt;br&gt;</code></td><td><code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;public class User \\{&lt;br&gt;    private String name;&lt;br&gt;    private Integer age;&lt;br&gt; &lt;br&gt;    public String getName() \\{&lt;br&gt;        return name;&lt;br&gt;    \\}&lt;br&gt; &lt;br&gt;    public void setName(String name) \\{&lt;br&gt;        this.name = name;&lt;br&gt;    \\}&lt;br&gt; &lt;br&gt;    public Integer getAge() \\{&lt;br&gt;        return age;&lt;br&gt;    \\}&lt;br&gt; &lt;br&gt;    public void setAge(Integer age) \\{&lt;br&gt;        this.age = age;&lt;br&gt;    \\}&lt;br&gt;\\}&lt;br&gt;</code></td></tr></tbody></table><p>（3）下面是一个简单的测试样例：</p><p><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></p><p>（4）如果传递的参数有前缀，且前缀与接收实体类的名称相同，那么参数也是可以正常传递的：</p><p><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></p><p><strong>2</strong>**，指定参数前缀** （1）如果传递的参数有前缀，且前缀与接收实体类的名称不同相，那么参数无法正常传递：</p><p><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></p><p>（2）我们可以结合 <strong>@InitBinder</strong> 解决这个问题，通过参数预处理来指定使用的前缀为 <strong>u</strong>.     除了在 <strong>Controller</strong> 里单独定义预处理方法外，我们还可以通过 <strong>@ControllerAdvice</strong> 结合 <strong>@InitBinder</strong> 来定义全局的参数预处理方法，方便各个 <strong>Controller</strong> 使用。具体做法参考我之前的文章：</p><ul><li><a href="https://www.hangge.com/blog/cache/detail_2483.html" target="_blank" rel="noreferrer">SpringBoot - @ControllerAdvice</a>的使用详解3（请求参数预处理 @InitBinder）</li></ul><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;14&lt;br&gt;15&lt;br&gt;16&lt;br&gt;17&lt;br&gt;</code></td><td><code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;import org.springframework.web.bind.WebDataBinder;&lt;br&gt;import org.springframework.web.bind.annotation.*;&lt;br&gt; &lt;br&gt;@RestController&lt;br&gt;public class HelloController \\{&lt;br&gt;    @GetMapping(&quot;/hello&quot;)&lt;br&gt;    public String hello(@ModelAttribute(&quot;u&quot;) User user) \\{&lt;br&gt;        return &quot;name&lt;br&gt;</code>&lt;br&gt;&lt;br&gt;：&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;&quot; + user.getName() + &quot;\\&lt;br\\&gt; age&lt;br&gt;</code>&lt;br&gt;&lt;br&gt;：&lt;br&gt;&lt;br&gt;<code>&lt;br&gt;&quot; + user.getAge();&lt;br&gt;    \\}&lt;br&gt; &lt;br&gt;    @InitBinder(&quot;u&quot;)&lt;br&gt;    private void initBinder(WebDataBinder binder) \\{&lt;br&gt;        binder.setFieldDefaultPrefix(&quot;u.&quot;);&lt;br&gt;    \\}&lt;br&gt;\\}&lt;br&gt;</code></td></tr></tbody></table><p>（3）重启程序可以看到参数以及成功接收了：</p><p><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></p><p><strong>3</strong>**，构造多个对象来接收参数** （1）如果一个 <strong>get</strong> 请求的参数分属不同的对象，也可以使用多个对象来接收参数：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>```&lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;- （2）新增的 <strong>Phone</strong> 类定义如下：</td><td></td></tr></tbody></table><ul><li>| | |</li><li>|---|---|</li><li>| &lt;br&gt;1&lt;br&gt;2&lt;br&gt;3&lt;br&gt;4&lt;br&gt;5&lt;br&gt;6&lt;br&gt;7&lt;br&gt;8&lt;br&gt;9&lt;br&gt;10&lt;br&gt;11&lt;br&gt;12&lt;br&gt;13&lt;br&gt;<code>|</code>&lt;br&gt;package com.example.demo;&lt;br&gt; &lt;br&gt;public class Phone {&lt;br&gt;    private String number;&lt;br&gt; &lt;br&gt;    public String getNumber() {&lt;br&gt;        return number;&lt;br&gt;    }&lt;br&gt; &lt;br&gt;    public void setNumber(String number) {&lt;br&gt;        this.number = number;&lt;br&gt;    }&lt;br&gt;}&lt;br&gt;```|</li></ul><p>（3）下面是一个简单的测试样例：</p><p><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a></p><p>原文出自：<a href="https://www.hangge.com/" target="_blank" rel="noreferrer">www.hangge.com</a>  转载请保留原文链接： <a href="https://www.hangge.com/blog/cache/detail_2484.html" target="_blank" rel="noreferrer">https://www.hangge.com/blog/cache/detail_2484.html</a> &gt; 来自 &lt;<a href="https://www.hangge.com/blog/cache/detail_2484.html" target="_blank" rel="noreferrer">https://www.hangge.com/blog/cache/detail_2484.html</a>&gt; <a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a> <a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a><a href="https://www.hangge.com/blog/cache/detail_2484.html#" target="_blank" rel="noreferrer"></a> &gt; 来自 &lt;<a href="https://www.hangge.com/blog/cache/detail_2484.html" target="_blank" rel="noreferrer">https://www.hangge.com/blog/cache/detail_2484.html</a>&gt;</p></div>',1)])])}const c=r(b,[["render",o]]);export{s as __pageData,c as default};
